            { q: "Pemilihan metode tafsir yang tepat bergantung pada ....", options: ["Tujuan penafsiran dan kebutuhan pembaca", "Selalu menggunakan metode tahlili tanpa pertimbangan", "Panjang pendeknya surah semata", "Bahasa asli penafsir semata"], correct: 0 }
